export const UNTITLED_VIDEO = "Video guardado";

type TitleMetadata = { title?: string; description?: string };

function compact(value: string): string {
  return value.replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim();
}

// Recognize only names generated by our old quick-save flow, never arbitrary personal titles.
export function isAutomaticTitle(name: string): boolean {
  return name === UNTITLED_VIDEO || /^(Instagram|TikTok|YouTube|Otra plataforma) · \d{2}[-/]\d{2},? \d{2}:\d{2}$/.test(name);
}

function usefulTitle(value: string): string {
  const text = compact(value);
  if (!text || /^(?:video|reel|instagram|tiktok|youtube|video guardado)$/i.test(text) ||
      /^(?:video|reel) by /i.test(text) || /^https?:\/\//i.test(text)) return "";
  return text;
}

function shorten(text: string): string {
  return text.length <= 200 ? text : text.slice(0, 199).replace(/[\uD800-\uDBFF]$/, "").trimEnd() + "…";
}

export function contentTitle(metadata?: TitleMetadata): string {
  // Instagram often calls a clip "Video by <account>"; its caption describes the content.
  const description = metadata?.description?.replace(/https?:\/\/\S+/gi, " ") ?? "";
  return shorten(usefulTitle(metadata?.title ?? "") || usefulTitle(description));
}

export function videoTitle(name: string, metadata?: TitleMetadata): string {
  return isAutomaticTitle(name) ? contentTitle(metadata) || UNTITLED_VIDEO : name;
}

export function sharedTitle(text: string): string {
  return shorten(usefulTitle(text.replace(/https?:\/\/\S+|www\.\S+/gi, " ")));
}
